// Doing this (define below) results in 0 second compile times (versues 5 second)
// (when I added it I thought that something wasn't working right and that's why I got instant compilation)
#define LOOP_ZERO float(min(iFrame, 0))

#define FOCAL_LEN 1.5

mat2 rotMat(float r){ return  mat2(cos(r), -sin(r), sin(r), cos(r)); }

vec3 rotX(in vec3 p, float r)
{
    p.yz *= rotMat(r); return p;
}

vec3 rotY(in vec3 p, float r)
{
    p.xz *= rotMat(r); return p;
}

vec3 rotZ(in vec3 p, float r)
{
    p.xy *= rotMat(r); return p;
}

vec3 getVolume(vec3 p)
{
    vec3 a = vec3(0);
    float g = 1.;

    for(int i = 0; i < 4; i++)
    {
        a += texture(iChannel0, rotY(p*0.01, 1.)/g).rgb*g;
        g *= 0.5;
    }

    float m = smoothstep(10., -20., (p.y));
    vec3 r = pow(a*0.9, vec3(4.*(1.-m)))*m*3.;
    r = mix(r, vec3(length(r)), 0.5);
    return r;
}

vec3 castRay(vec3 ro, vec3 rd, float steps, float dist)
{
    vec3 accumulate = vec3(0);
    vec3 p = ro;
    float stepSize = dist/steps;
    for(float i = LOOP_ZERO; i < steps; i++)
    {
        vec3 volume = getVolume(p);
        accumulate += volume*stepSize;
        p += rd*stepSize;
    }
    return accumulate/dist;
}

vec3 renderVolume(vec3 ro, vec3 rd, vec3 lgt, float primarySteps, float primaryDist, float shadowSteps, float shadowDist)
{
    vec3 accumulate = vec3(0);
    vec3 p = ro;
    float stepSize = primaryDist/primarySteps;
    for(float i = LOOP_ZERO; i < primarySteps; i++)
    {
        vec3 volume = getVolume(p);
        float shadow = length(castRay(p, lgt, shadowSteps, shadowDist));
        accumulate += volume*stepSize/(shadow+1.);
        p += rd*stepSize;
    }
    return accumulate/primaryDist;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;
    vec2 m =  (iMouse.xy-iResolution.xy*0.5)/iResolution.y*step(0.01, iMouse.z);

    vec2 rot = vec2(0, 0)-m.xy*4.;
    vec3 ro = vec3(0, sin(iTime*0.5)*3., iTime*10.);
    vec3 rd = rotY(rotX(normalize(vec3(uv, FOCAL_LEN)), rot.y), rot.x);

    vec3 col = renderVolume(ro, rd, vec3(0, 1, 0), 100., 50., 5., 25.);

    // Output to screen
    fragColor = vec4(col,1.0);
}
